"use client";
import { useRef, type ReactNode } from "react";
import { useScrollMotion, type ScrollMotionProps } from "./scroll-shared";
export interface HideHeaderProps extends ScrollMotionProps {
  children: ReactNode;
  threshold?: number;
  visibleAtTop?: number;
  duration?: number;
  visibleZones?: readonly (readonly [number, number])[];
  onHiddenChange?: (hidden: boolean) => void;
  position?: "sticky" | "fixed" | "absolute";
}
/** Direction hysteresis prevents trackpad jitter. Keyboard focus always brings navigation back. */
export function HideHeader({
  children,
  threshold = 12,
  visibleAtTop = 60,
  duration = 0.3,
  visibleZones = [],
  onHiddenChange,
  position = "sticky",
  ...props
}: HideHeaderProps) {
  const root = useRef<HTMLElement>(null),
    state = useRef({ offset: 0, anchor: 0, direction: 0, hidden: false }),
    callback = useRef(onHiddenChange);
  callback.current = onHiddenChange;
  useScrollMotion(
    root,
    { ...props, scrub: 0 },
    ({ offset, reduced }) => {
      const el = root.current!,
        s = state.current,
        delta = offset - s.offset,
        dir = Math.sign(delta);
      if (dir && dir !== s.direction) {
        s.anchor = s.offset;
        s.direction = dir;
      }
      s.offset = offset;
      let hidden = s.hidden;
      if (
        reduced ||
        offset <= visibleAtTop ||
        visibleZones.some(([a, b]) => offset >= a && offset <= b) ||
        el.contains(document.activeElement)
      )
        hidden = false;
      else if (Math.abs(offset - s.anchor) >= threshold) hidden = s.direction > 0;
      el.style.transform = `translateY(${hidden ? "calc(-100% - 2px)" : "0"})`;
      el.style.transition = reduced ? "none" : `transform ${duration}s cubic-bezier(.22,1,.36,1)`;
      el.dataset.hidden = String(hidden);
      if (hidden !== s.hidden) {
        s.hidden = hidden;
        callback.current?.(hidden);
      }
    },
    `${threshold}:${visibleAtTop}:${duration}:${JSON.stringify(visibleZones)}`,
    true,
    true,
  );
  return (
    <header
      ref={root}
      data-scroll-animation="hide-header"
      className={props.className}
      onFocusCapture={() => {
        const el = root.current!;
        el.style.transform = "translateY(0)";
        el.dataset.hidden = "false";
        if (state.current.hidden) {
          state.current.hidden = false;
          callback.current?.(false);
        }
      }}
      style={{ position, top: 0, left: 0, right: 0, zIndex: 20, ...props.style }}
    >
      {children}
    </header>
  );
}
